export default "<!doctype html>\n<html lang=\"th\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>แอป JAC — ติดตามการเรียน</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Anuphan:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n/* One quiet page; the only loud thing is the readiness ruler with its yellow pass line. */\n:root{ --bg:#F6F7F5; --surf:#FFFFFF; --ink:#17202B; --mute:#6A7480; --faint:#9AA3AD; --line:#E6E9EC; --track:#EEF0F2;\n  --pass:#F5B800; --ok:#1E9E6A; --mid:#D99A00; --low:#D64545; --none:#C9CFD5; --r:14px }\n@media (prefers-color-scheme: dark){ :root{ --bg:#0F1419; --surf:#171D24; --ink:#E8ECF0; --mute:#97A2AE; --faint:#6B7682; --line:#262E37; --track:#222A33; --none:#3A444F } }\n*{ box-sizing:border-box } html{ -webkit-text-size-adjust:100% }\nbody{ margin:0; background:var(--bg); color:var(--ink); font:15px/1.55 'Anuphan', system-ui, sans-serif; font-variant-numeric:tabular-nums }\nmain{ max-width:720px; margin:0 auto; padding:20px 16px 64px }\nbutton{ font:inherit; color:inherit }\n.head{ display:flex; align-items:center; justify-content:space-between; gap:12px }\nh1{ font-size:22px; font-weight:700; margin:0; letter-spacing:-.01em }\n.livechip{ display:inline-flex; align-items:center; gap:8px; padding:6px 12px; border-radius:999px; background:var(--surf); border:1px solid var(--line); font-size:13px; color:var(--mute); white-space:nowrap }\n.dot{ width:8px; height:8px; border-radius:50%; background:var(--none) } .dot.on{ background:var(--ok); box-shadow:0 0 0 0 rgba(30,158,106,.5); animation:p 1.8s infinite }\n@keyframes p{ to{ box-shadow:0 0 0 8px rgba(30,158,106,0) } } @media (prefers-reduced-motion:reduce){ .dot.on{ animation:none } }\n.note{ color:var(--mute); font-size:13px; margin:6px 0 0 }\n/* today: three numbers in one strip */\n.today{ display:grid; grid-template-columns:repeat(3,1fr); margin:0 0 8px; background:var(--surf); border:1px solid var(--line); border-radius:var(--r) }\n.today div{ padding:14px 16px } .today div + div{ border-left:1px solid var(--line) }\n.today b{ display:block; font-size:28px; font-weight:700; line-height:1.15 } .today span{ font-size:13px; color:var(--mute); white-space:nowrap } .today small{ font-size:12px; color:var(--faint); font-weight:500 }\n.subline{ font-size:13px; color:var(--mute); margin:0 2px 26px }\nh2{ font-size:15px; font-weight:700; margin:28px 0 10px; display:flex; justify-content:space-between; align-items:baseline } h2 small{ font-weight:500; color:var(--mute); font-size:13px }\n.panel{ background:var(--surf); border:1px solid var(--line); border-radius:var(--r) }\n/* people */\n.prow{ display:grid; grid-template-columns:40px minmax(0,1fr) auto auto 14px; gap:12px; align-items:center; width:100%; padding:12px 14px; border:0; background:none; text-align:left; cursor:pointer; border-top:1px solid var(--line) }\n.prow:first-child{ border-top:0 } .prow:hover{ background:var(--track) } .prow:focus-visible{ outline:2px solid var(--pass); outline-offset:-2px; border-radius:var(--r) }\n.av{ width:40px; height:40px; border-radius:50%; object-fit:cover; background:var(--track); display:grid; place-items:center; font-weight:700; color:var(--mute); font-size:15px }\n.pn{ min-width:0 } .pn b{ display:block; font-weight:600; white-space:nowrap; overflow:hidden; text-overflow:ellipsis } .pn span{ font-size:12.5px; color:var(--mute) }\n.pn .on{ color:var(--ok); font-weight:600 }\n.pt{ text-align:right; font-size:13px; color:var(--mute); line-height:1.3 } .pt b{ display:block; color:var(--ink); font-size:15px; font-weight:600 }\n.chip{ min-width:52px; text-align:center; font-size:13px; font-weight:700; padding:4px 8px; border-radius:8px; background:var(--track); color:var(--mute) }\n.chip.ok{ background:rgba(30,158,106,.12); color:var(--ok) } .chip.mid{ background:rgba(217,154,0,.14); color:#A87700 } .chip.low{ background:rgba(214,69,69,.12); color:var(--low) }\n@media (prefers-color-scheme: dark){ .chip.mid{ color:#F0B93A } }\n.chev{ color:var(--faint) }\n.more{ display:block; width:100%; padding:12px; border:0; border-top:1px solid var(--line); background:none; color:var(--mute); font-size:13px; cursor:pointer }\n/* 14 days */\n.bars{ display:grid; grid-template-columns:repeat(14,1fr); gap:6px; align-items:end; height:120px; padding:16px 16px 0 }\n.bars div{ display:flex; flex-direction:column; justify-content:flex-end; align-items:center; height:100%; gap:4px } .bars i{ display:block; width:100%; max-width:22px; border-radius:5px; background:var(--none); min-height:3px }\n.bars i.v{ background:var(--ink) } .bars .t i.v{ background:var(--pass) } .bars em{ font-style:normal; font-size:11px; color:var(--mute) }\n.days{ display:grid; grid-template-columns:repeat(14,1fr); gap:6px; padding:6px 16px 14px; font-size:11px; color:var(--faint); text-align:center } .days .t{ color:var(--ink); font-weight:700 }\ndetails.extra{ margin-top:28px } details.extra > summary{ cursor:pointer; list-style:none; font-weight:700; font-size:15px; padding:4px 0 } details.extra > summary::-webkit-details-marker{ display:none }\ndetails.extra > summary::after{ content:' ＋'; color:var(--mute) } details.extra[open] > summary::after{ content:' －' }\ntable{ width:100%; border-collapse:collapse; font-size:14px } th,td{ text-align:left; padding:10px 14px; border-top:1px solid var(--line) } tr:first-child th{ border-top:0 } th{ color:var(--mute); font-weight:500; font-size:13px } td.n,th.n{ text-align:right }\n.hours{ display:grid; grid-template-columns:repeat(24,1fr); gap:3px; align-items:end; height:64px; padding:14px 14px 0 } .hours i{ display:block; background:var(--ink); opacity:.85; border-radius:3px 3px 0 0; min-height:2px }\n.hl{ display:grid; grid-template-columns:repeat(24,1fr); font-size:10.5px; color:var(--faint); text-align:center; padding:4px 14px 12px }\n.empty{ color:var(--mute); text-align:center; padding:22px; font-size:14px }\n#gate{ padding:18px; margin:22px 0 } #gate input{ width:100%; padding:12px 14px; border-radius:10px; border:1px solid var(--line); background:var(--bg); color:var(--ink); font:inherit; margin:10px 0 }\n.btn{ border:0; border-radius:10px; padding:11px 18px; background:var(--ink); color:var(--surf); font-weight:600; cursor:pointer }\n\n/* ---------- person sheet ---------- */\ndialog{ border:0; padding:0; margin:auto 0 0; width:100%; max-width:100%; max-height:94vh; border-radius:20px 20px 0 0; background:var(--bg); color:var(--ink) }\n@media (min-width:760px){ dialog{ margin:auto; width:720px; border-radius:20px } }\ndialog::backdrop{ background:rgba(10,15,20,.55) }\n.dhead{ position:sticky; top:0; z-index:2; display:flex; align-items:center; gap:12px; padding:16px; background:var(--bg); border-bottom:1px solid var(--line) }\n.dhead .av{ width:48px; height:48px; font-size:18px } .dhead h3{ margin:0; font-size:18px; font-weight:700 } .dhead p{ margin:0; font-size:13px; color:var(--mute) }\n.close{ margin-left:auto; border:1px solid var(--line); background:var(--surf); border-radius:10px; padding:8px 14px; cursor:pointer }\n.dbody{ padding:16px 16px 32px }\n.tabs{ display:flex; gap:6px; padding:4px; background:var(--track); border-radius:12px; margin-bottom:18px }\n.tabs button{ flex:1; border:0; background:none; padding:9px 6px; border-radius:9px; font-size:14px; color:var(--mute); cursor:pointer; white-space:nowrap }\n.tabs button.on{ background:var(--surf); color:var(--ink); font-weight:700; box-shadow:0 1px 2px rgba(0,0,0,.08) }\n.verdict{ font-size:13px; font-weight:700; display:inline-block; padding:3px 10px; border-radius:999px; margin-bottom:6px }\n.verdict.ok{ background:rgba(30,158,106,.12); color:var(--ok) } .verdict.mid{ background:rgba(217,154,0,.14); color:#A87700 } .verdict.low{ background:rgba(214,69,69,.12); color:var(--low) }\n.score{ display:flex; align-items:baseline; gap:14px; flex-wrap:wrap } .score b{ font-size:48px; font-weight:700; line-height:1 } .score span{ color:var(--mute); font-size:14px }\n/* the ruler: 0–100 with ticks, the pass line at 75 */\n.ruler{ position:relative; height:64px; margin:18px 0 6px }\n.ruler .track{ position:absolute; left:0; right:0; top:22px; height:12px; border-radius:6px; background:var(--track); overflow:hidden }\n.ruler .fill{ position:absolute; left:0; top:0; bottom:0; border-radius:6px }\n.ruler .ticks{ position:absolute; left:0; right:0; top:38px; height:8px; background:repeating-linear-gradient(90deg, var(--faint) 0 1px, transparent 1px 10%) }\n.ruler .tl{ position:absolute; top:46px; font-size:11px; color:var(--faint); transform:translateX(-50%) }\n.ruler .passln{ position:absolute; top:10px; bottom:16px; width:3px; margin-left:-1.5px; background:var(--pass); border-radius:2px }\n.ruler .passlb{ position:absolute; top:-8px; transform:translateX(-50%); font-size:11.5px; font-weight:700; color:#A87700; white-space:nowrap } @media (prefers-color-scheme: dark){ .ruler .passlb{ color:var(--pass) } }\n.ruler .mk{ position:absolute; top:17px; width:22px; height:22px; margin-left:-11px; border-radius:50%; background:var(--surf); border:4px solid var(--ink) }\n.ruler .mock{ position:absolute; top:36px; width:0; height:0; margin-left:-6px; border:6px solid transparent; border-bottom:8px solid var(--mute); top:24px }\n.legend{ display:flex; gap:16px; flex-wrap:wrap; font-size:12.5px; color:var(--mute) } .legend i{ display:inline-block; width:10px; height:10px; border-radius:50%; margin-right:5px; vertical-align:-1px }\n.facts{ display:grid; grid-template-columns:repeat(3,1fr); margin:20px 0; background:var(--surf); border:1px solid var(--line); border-radius:var(--r) }\n.facts div{ padding:12px 14px } .facts div + div{ border-left:1px solid var(--line) } .facts b{ display:block; font-size:20px; font-weight:700 } .facts span{ font-size:12.5px; color:var(--mute) }\n.cat{ display:grid; grid-template-columns:minmax(0,1fr) 46px; gap:4px 12px; padding:12px 14px; border-top:1px solid var(--line) } .cat:first-child{ border-top:0 }\n.cat .nm{ font-weight:600; font-size:14px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis } .cat .pc{ text-align:right; font-weight:700; font-size:15px }\n.cat .bar{ grid-column:1 / -1; position:relative; height:8px; border-radius:4px; background:var(--track) } .cat .bar i{ position:absolute; left:0; top:0; bottom:0; border-radius:4px }\n.cat .bar u{ position:absolute; top:-3px; bottom:-3px; left:75%; width:2px; background:var(--pass); text-decoration:none }\n.cat .meta{ grid-column:1 / -1; font-size:12.5px; color:var(--mute) } .cat .meta .todo{ color:var(--low); font-weight:600 }\n.todo-list{ margin:0; padding:0; list-style:none } .todo-list li{ display:flex; gap:12px; padding:12px 14px; border-top:1px solid var(--line); font-size:14px } .todo-list li:first-child{ border-top:0 }\n.todo-list .k{ flex:none; width:22px; height:22px; border-radius:50%; background:var(--pass); color:#17202B; font-size:12px; font-weight:700; display:grid; place-items:center; margin-top:1px }\n.track14{ display:grid; grid-template-columns:repeat(14,1fr); gap:4px; padding:14px } .track14 i{ height:28px; border-radius:5px; background:var(--track) }\n.track14 i.l1{ background:rgba(30,158,106,.35) } .track14 i.l2{ background:rgba(30,158,106,.65) } .track14 i.l3{ background:var(--ok) }\n.both{ display:flex; justify-content:space-between; align-items:center; gap:12px; padding:14px; margin-bottom:18px; background:var(--surf); border:1px solid var(--line); border-radius:var(--r) }\n.both b{ font-size:24px } .both span{ font-size:13px; color:var(--mute) }\n.fine{ font-size:12px; color:var(--faint); margin-top:10px }\n</style>\n</head>\n<body><main>\n<div class=\"head\"><h1>ติดตามการเรียน</h1><span class=\"livechip\" id=\"live\"><span class=\"dot\"></span>กำลังโหลด</span></div>\n<p class=\"note\">แอป JAC · เวลาญี่ปุ่น · อัปเดตเองทุก 30 วินาที</p>\n<div id=\"gate\" class=\"panel\" style=\"display:none\"><b>ใส่รหัสผ่านเพื่อดูหน้านี้</b><input id=\"key\" type=\"password\" autocomplete=\"current-password\"><button class=\"btn\" id=\"go\">เปิด</button><div id=\"gmsg\" class=\"note\"></div></div>\n<div id=\"dash\" hidden>\n  <h2 style=\"margin-top:22px\">วันนี้</h2>\n  <div class=\"today\" id=\"kpis\"></div>\n  <div class=\"subline\" id=\"kpisub\"></div>\n  <h2>คนที่ใช้แอป <small id=\"pcount\"></small></h2>\n  <div class=\"panel\" id=\"people\"></div>\n  <h2>คนที่ทำแบบทดสอบ 14 วัน <small>สีเหลือง = วันนี้</small></h2>\n  <div class=\"panel\"><div class=\"bars\" id=\"chart\"></div><div class=\"days\" id=\"chartd\"></div></div>\n  <details class=\"extra\"><summary>รายละเอียดเพิ่มเติม</summary>\n    <h2>วันนี้แยกตามภาค</h2><div class=\"panel\" id=\"parts\"></div>\n    <h2>สอบจำลอง 14 วัน</h2><div class=\"panel\" id=\"mocks\"></div>\n    <h2>ช่วงเวลาที่ทำบ่อย <small>7 วัน</small></h2><div class=\"panel\"><div class=\"hours\" id=\"hours\"></div><div class=\"hl\" id=\"hl\"></div></div>\n    <h2>กิจกรรมล่าสุด</h2><div class=\"panel\" id=\"recent\"></div>\n    <p class=\"fine\">คนที่ไม่ตั้งชื่อเล่น นับจากเครือข่ายและรุ่นมือถือ — มือถือเครื่องเดียวกันที่เปิดหลายเบราว์เซอร์นับเป็น 1 คน ตัวเลขจึงเป็นค่าประมาณ</p>\n  </details>\n</div>\n</main>\n<dialog id=\"dlg\"><div id=\"dlgBody\"></div></dialog>\n<script>\nvar PART = { gakka: 'ทฤษฎี', jitsugi: 'ปฏิบัติ 土木', life: 'ปฏิบัติ ไลฟ์ไลน์', '': '—' };\nvar PTAB = { gakka: 'ทฤษฎี', jitsugi: '土木', life: 'ไลฟ์ไลน์' };\nvar MODE = { asst: 'ผู้ช่วยฝึก', real: 'สอบจำลอง', mini: 'ทดสอบย่อย', all: 'ทำทุกข้อ', wrong: 'ข้อที่เคยผิด', fav: 'ติดดาว', weak: 'จุดอ่อน', review: 'ทบทวน', hot: 'ข้อที่ออกสอบ' };\nfunction $(id){ return document.getElementById(id); }\nfunction pct(s, n){ return n ? Math.round(s / n * 100) + '%' : '—'; }\nfunction ago(ts, now){ var m = Math.round((now - ts) / 60000); if (m < 1) return 'เมื่อสักครู่'; if (m < 60) return m + ' นาทีที่แล้ว'; var h = Math.round(m / 60); if (h < 24) return h + ' ชม.ที่แล้ว'; return Math.round(h / 24) + ' วันที่แล้ว'; }\nfunction esc(v){ return String(v == null ? '' : v).replace(/[&<>\"']/g, function(c){ return { '&':'&amp;', '<':'&lt;', '>':'&gt;', '\"':'&quot;', \"'\":'&#39;' }[c]; }); }\nfunction lvl(v){ return v == null ? '' : v >= 75 ? 'ok' : v >= 60 ? 'mid' : 'low'; }\nfunction avatar(src, name){ return src ? '<img class=\"av\" src=\"' + src + '\" alt=\"\">' : '<span class=\"av\">' + esc((name || '?').slice(0, 1)) + '</span>'; }\nvar showAll = false, last = null;\n\nfunction renderPeople(d){\n  var ps = d.people || [];\n  // people who never answered anything and set no name are folded away\n  var main = ps.filter(function(p){ return p.name || p.n_all; }), rest = ps.length - main.length;\n  var list = showAll ? ps : main;\n  $('pcount').textContent = main.length + ' คน' + (rest ? ' · ไม่ระบุชื่อที่ยังไม่ได้ทำ ' + rest : '');\n  $('people').innerHTML = (list.length ? list.map(function(p){\n    var on = d.now - p.last < 5 * 60000, acc = p.n_all ? Math.round(p.s_all / p.n_all * 100) : null;\n    return '<button class=\"prow\" data-k=\"' + esc(p.k) + '\">' + avatar(p.avatar, p.name) +\n      '<span class=\"pn\"><b>' + (p.name ? esc(p.name) : 'ไม่ระบุชื่อ') + '</b><span>' + (on ? '<span class=\"on\">กำลังใช้อยู่</span>' : ago(p.last, d.now)) + (p.devices > 1 ? ' · ' + p.devices + ' เครื่อง' : '') + '</span></span>' +\n      '<span class=\"pt\"><b>' + (p.n_today || 0) + '</b>ข้อวันนี้</span>' +\n      '<span class=\"chip ' + lvl(acc) + '\" title=\"ตอบถูกรวม\">' + (acc == null ? '—' : acc + '%') + '</span><span class=\"chev\">›</span></button>';\n  }).join('') : '<div class=\"empty\">ยังไม่มีใครใช้แอป</div>') +\n    (rest ? '<button class=\"more\" id=\"showAll\">' + (showAll ? 'ซ่อนคนที่ไม่ระบุชื่อและยังไม่ได้ทำ' : 'แสดงทั้งหมด (+' + rest + ')') + '</button>' : '');\n}\nfunction render(d){\n  last = d; $('dash').hidden = false;\n  var liveN = d.live.reduce(function(a, x){ return a + x.c; }, 0);\n  $('live').innerHTML = '<span class=\"dot ' + (liveN ? 'on' : '') + '\"></span>' + (liveN ? liveN + ' คนกำลังใช้' : 'ไม่มีใครใช้อยู่');\n  var t = d.t || {};\n  $('kpis').innerHTML = '<div><b>' + d.opensToday + '</b><span>คนเปิดแอป</span></div><div><b>' + (t.devs || 0) + '</b><span>คนทำข้อสอบ</span></div><div><b>' + (t.n || 0) + '</b><span>ข้อที่ตอบ</span></div>';\n  $('kpisub').textContent = 'ตอบถูก ' + pct(t.s, t.n) + ' · ' + (t.quizzes || 0) + ' ชุด · ผู้ใช้ 7 วัน ' + d.devs7 + ' คน' + (d.devicesToday > d.opensToday ? ' · จาก ' + d.devicesToday + ' เครื่อง' : '');\n  renderPeople(d);\n  var byDay = {}; d.days.forEach(function(x){ byDay[x.day] = x; });\n  var list = []; for (var i = 13; i >= 0; i--) { var day = new Date(d.now + 9 * 3600e3 - i * 864e5).toISOString().slice(0, 10); list.push({ day: day, v: byDay[day] ? byDay[day].devs : 0 }); }\n  var max = Math.max.apply(null, list.map(function(x){ return x.v; }).concat([1]));\n  $('chart').innerHTML = list.map(function(x){ return '<div class=\"' + (x.day === d.today ? 't' : '') + '\"><em>' + (x.v || '') + '</em><i class=\"' + (x.v ? 'v' : '') + '\" style=\"height:' + Math.max(3, Math.round(x.v / max * 86)) + 'px\"></i></div>'; }).join('');\n  $('chartd').innerHTML = list.map(function(x){ return '<span class=\"' + (x.day === d.today ? 't' : '') + '\">' + +x.day.slice(8) + '</span>'; }).join('');\n  $('parts').innerHTML = d.parts.length ? '<table><tr><th>ภาค</th><th class=\"n\">ชุด</th><th class=\"n\">ข้อ</th><th class=\"n\">ถูก</th></tr>' + d.parts.map(function(p){ return '<tr><td>' + (PART[p.part] || p.part) + '</td><td class=\"n\">' + p.quizzes + '</td><td class=\"n\">' + p.n + '</td><td class=\"n\">' + pct(p.s, p.n) + '</td></tr>'; }).join('') + '</table>' : '<div class=\"empty\">วันนี้ยังไม่มีใครทำแบบทดสอบ</div>';\n  $('mocks').innerHTML = d.mocks.length ? '<table><tr><th>ภาค</th><th class=\"n\">ครั้ง</th><th class=\"n\">ผ่าน 75%</th></tr>' + d.mocks.map(function(m){ return '<tr><td>' + (PART[m.part] || m.part) + '</td><td class=\"n\">' + m.c + '</td><td class=\"n\">' + m.pass + ' (' + pct(m.pass, m.c) + ')</td></tr>'; }).join('') + '</table>' : '<div class=\"empty\">ยังไม่มีการสอบจำลอง</div>';\n  var hs = []; for (var h = 0; h < 24; h++) hs.push(0); d.hours.forEach(function(x){ hs[x.h] = x.c; }); var hm = Math.max.apply(null, hs.concat([1]));\n  $('hours').innerHTML = hs.map(function(c){ return '<i style=\"height:' + Math.round(c / hm * 100) + '%\" title=\"' + c + '\"></i>'; }).join('');\n  $('hl').innerHTML = hs.map(function(c, h){ return '<span>' + (h % 3 ? '' : h) + '</span>'; }).join('');\n  $('recent').innerHTML = d.recent.length ? '<table><tr><th>เวลา</th><th>ใคร</th><th>ทำอะไร</th><th class=\"n\">คะแนน</th></tr>' + d.recent.map(function(r){ return '<tr><td>' + ago(r.ts, d.now) + '</td><td>' + esc(r.name || 'ไม่ระบุชื่อ') + '</td><td>' + (PART[r.part] || r.part) + ' · ' + (MODE[r.mode] || r.mode) + '</td><td class=\"n\">' + r.s + '/' + r.n + '</td></tr>'; }).join('') + '</table>' : '<div class=\"empty\">ยังไม่มีข้อมูล</div>';\n}\n\n/* ---------- readiness estimate (same maths as in the app) ---------- */\nfunction binomAtLeast(n, k, p){ var t = 0, c = 1; for (var i = 0; i <= n; i++) { if (i > 0) c = c * (n - i + 1) / i; if (i >= k) t += c * Math.pow(p, i) * Math.pow(1 - p, n - i); } return Math.min(1, Math.max(0, t)); }\nfunction analysePart(cats, meta, mocks){\n  var tot = cats.reduce(function(a, c){ return a + c.total; }, 0), C = 0, T = 0;\n  cats.forEach(function(c){ C += c.c; T += c.t; if (c.tried == null) c.tried = Math.max(c.done, c.done + c.wrong); });\n  var base = T ? C / T : .5, exp = 0;\n  cats.forEach(function(c){ c.w = c.total / tot; c.acc = c.t ? c.c / c.t : null; c.est = (c.c + 3 * base) / (c.t + 3); exp += c.w * c.est; });\n  var mockAvg = mocks.length ? mocks.slice(0, 3).reduce(function(a, m){ return a + m.s / m.n; }, 0) / Math.min(3, mocks.length) : null;\n  var p = mockAvg != null ? (exp + mockAvg) / 2 : exp;\n  var need = Math.ceil(meta.n * meta.pass / 100), prob = binomAtLeast(meta.n, need, p);\n  var weak = cats.filter(function(c){ return c.est < .8; }).map(function(c){ c.impact = c.w * (.85 - c.est) + (c.t < 5 ? c.w * .1 : 0); return c; }).sort(function(a, b){ return b.impact - a.impact; }).slice(0, 3);\n  return { tot: tot, p: p, prob: prob, need: need, mockAvg: mockAvg, answered: T,\n    done: cats.reduce(function(a, c){ return a + c.done; }, 0), tried: cats.reduce(function(a, c){ return a + c.tried; }, 0), weak: weak,\n    conf: T >= 150 ? 'ข้อมูลพอ' : T >= 50 ? 'ข้อมูลพอประมาณ' : 'ข้อมูลยังน้อย' };\n}\nfunction verdict(pr){ return pr >= 70 ? ['ok', 'พร้อมสอบ'] : pr >= 40 ? ['mid', 'ใกล้แล้ว'] : ['low', 'ยังไม่พร้อม']; }\nfunction partView(part, cats, meta, mocks){\n  var a = analysePart(cats, meta, mocks);\n  if (!a.answered) return '<div class=\"empty\">ยังไม่เคยทำข้อสอบภาคนี้</div>';\n  var pr = Math.round(a.prob * 100), sc = Math.round(a.p * 100), v = verdict(pr), col = v[0] === 'ok' ? 'var(--ok)' : v[0] === 'mid' ? 'var(--mid)' : 'var(--low)';\n  var h = '<span class=\"verdict ' + v[0] + '\">' + v[1] + '</span>' +\n    '<div class=\"score\"><b>' + sc + '%</b><span>คะแนนที่คาด · โอกาสผ่าน ' + pr + '%</span></div>' +\n    '<div class=\"ruler\"><div class=\"track\"><span class=\"fill\" style=\"width:' + sc + '%;background:' + col + '\"></span></div><div class=\"ticks\"></div>' +\n    [0, 25, 50, 100].map(function(x){ return '<span class=\"tl\" style=\"left:' + x + '%\">' + x + '</span>'; }).join('') +\n    '<span class=\"passln\" style=\"left:' + meta.pass + '%\"></span><span class=\"passlb\" style=\"left:' + meta.pass + '%\">ผ่าน ' + meta.pass + '%</span>' +\n    '<span class=\"mk\" style=\"left:' + sc + '%;border-color:' + col + '\"></span>' +\n    (a.mockAvg != null ? '<span class=\"mock\" style=\"left:' + Math.round(a.mockAvg * 100) + '%\" title=\"สอบจำลอง\"></span>' : '') + '</div>' +\n    '<div class=\"legend\"><span><i style=\"background:' + col + '\"></i>คะแนนที่คาด</span>' + (a.mockAvg != null ? '<span><i style=\"background:var(--mute);border-radius:2px\"></i>สอบจำลองเฉลี่ย ' + Math.round(a.mockAvg * 100) + '%</span>' : '') + '<span><i style=\"background:var(--pass);border-radius:2px\"></i>เกณฑ์ผ่าน ' + a.need + '/' + meta.n + ' ข้อ</span></div>';\n  h += '<div class=\"facts\"><div><b>' + a.tried + '/' + a.tot + '</b><span>ข้อที่ทำแล้ว</span></div><div><b>' + a.answered + '</b><span>ครั้งที่ตอบ</span></div><div><b>' + (a.mockAvg != null ? Math.round(a.mockAvg * 100) + '%' : '—') + '</b><span>สอบจำลอง</span></div></div>';\n  var tips = a.weak.map(function(c){ return '<li><span class=\"k\">!</span><span><b>' + esc(c.th) + '</b> — ' + (c.t < 5 ? 'แทบยังไม่ได้ฝึก' : 'ถูก ' + Math.round(c.acc * 100) + '%') + ', ออกสอบราว ' + Math.round(c.w * meta.n) + ' ข้อ' + (c.total - c.tried > 0 ? ', ยังไม่ทำ ' + (c.total - c.tried) + ' ข้อ' : '') + '</span></li>'; });\n  if (a.mockAvg == null) tips.push('<li><span class=\"k\">!</span><span>ยังไม่เคย<b>สอบจำลอง</b>ภาคนี้ — ควรลองแบบจับเวลา</span></li>');\n  if (tips.length) h += '<h2>ควรฝึกต่อ</h2><ul class=\"panel todo-list\">' + tips.join('') + '</ul>';\n  h += '<h2>แต่ละหมวด <small>เส้นเหลือง = 75%</small></h2><div class=\"panel\">' + cats.slice().sort(function(x, y){ return (x.acc == null ? -1 : x.acc) - (y.acc == null ? -1 : y.acc); }).map(function(c){\n    var ac = c.acc == null ? null : Math.round(c.acc * 100), k = lvl(ac), cc = k === 'ok' ? 'var(--ok)' : k === 'mid' ? 'var(--mid)' : k === 'low' ? 'var(--low)' : 'var(--none)', left = c.total - c.tried;\n    return '<div class=\"cat\"><span class=\"nm\">' + esc(c.th) + '</span><span class=\"pc\" style=\"color:' + cc + '\">' + (ac == null ? '—' : ac + '%') + '</span>' +\n      '<span class=\"bar\"><i style=\"width:' + (ac || 0) + '%;background:' + cc + '\"></i><u></u></span>' +\n      '<span class=\"meta\">ทำแล้ว ' + c.tried + '/' + c.total + (left ? ' · <span class=\"todo\">ยังไม่ทำ ' + left + '</span>' : '') + ' · ออกสอบราว ' + Math.round(c.w * meta.n * 10) / 10 + ' ข้อ</span></div>';\n  }).join('') + '</div><p class=\"fine\">เรียงจากหมวดที่อ่อนที่สุด · ' + a.conf + ' (ตอบ ' + a.answered + ' ครั้ง) · เป็นค่าประมาณจากอัตราตอบถูก ไม่ใช่การรับประกัน</p>';\n  return h;\n}\nvar dp = null, dpTab = '';\nfunction openPerson(k){\n  $('dlgBody').innerHTML = '<div class=\"empty\">กำลังโหลด…</div>'; $('dlg').showModal();\n  fetch('/api/person?k=' + encodeURIComponent(k), { cache: 'no-store', headers: { 'x-key': KEY } }).then(function(r){ return r.json(); }).then(function(d){ dp = d; dpTab = ''; drawPerson(); })\n    .catch(function(){ $('dlgBody').innerHTML = '<div class=\"empty\">โหลดไม่ได้ — ลองใหม่อีกครั้ง</div>'; });\n}\nfunction drawPerson(){\n  var d = dp, s = d.summary;\n  var parts = s ? ['gakka', 'jitsugi', 'life'].filter(function(p){ return s.cats.some(function(c){ return c.part === p && c.t; }); }) : [];\n  if (!dpTab) dpTab = parts[0] || '';\n  var h = '<div class=\"dhead\">' + avatar(d.avatar, d.name) + '<div><h3>' + esc(d.name || 'ไม่ระบุชื่อ') + '</h3><p>ใช้ล่าสุด ' + ago(d.last, d.now) + (d.devices > 1 ? ' · ' + d.devices + ' เครื่อง' : '') + (s && s.exam ? ' · สอบ ' + esc(s.exam) : '') + '</p></div><button class=\"close\" id=\"dlgClose\">ปิด</button></div><div class=\"dbody\">';\n  // both parts are needed on exam day: 学科 + the 実技 track studied more\n  if (s && parts.length) {\n    var res = {};\n    parts.forEach(function(p){ var a = analysePart(s.cats.filter(function(c){ return c.part === p; }), s.parts[p] || { n: 25, pass: 75 }, d.events.filter(function(e){ return e.part === p && e.mode === 'real'; })); res[p] = a; });\n    var tr = res.life && (!res.jitsugi || res.life.answered > res.jitsugi.answered) ? 'life' : 'jitsugi';\n    if (res.gakka && res[tr]) { var both = Math.round(res.gakka.prob * res[tr].prob * 100), vb = verdict(both);\n      h += '<div class=\"both\"><div><span>โอกาสผ่านทั้ง 2 ภาค (ทฤษฎี + ' + PTAB[tr] + ')</span><br><b>' + both + '%</b></div><span class=\"verdict ' + vb[0] + '\">' + vb[1] + '</span></div>'; }\n    if (parts.length > 1) h += '<div class=\"tabs\">' + parts.map(function(p){ return '<button data-tab=\"' + p + '\" class=\"' + (p === dpTab ? 'on' : '') + '\">' + PTAB[p] + '</button>'; }).join('') + '</div>';\n    h += partView(dpTab, s.cats.filter(function(c){ return c.part === dpTab; }), s.parts[dpTab] || { n: 25, pass: 75 }, d.events.filter(function(e){ return e.part === dpTab && e.mode === 'real'; }));\n  } else h += '<div class=\"empty\">ยังไม่มีข้อมูลรายหมวด — ต้องเปิดแอปเวอร์ชันใหม่และทำแบบทดสอบก่อน</div>';\n  // 14 days as a row of squares\n  var byDay = {}; d.days.forEach(function(x){ byDay[x.day] = x.n; }); var arr = [];\n  for (var i = 13; i >= 0; i--) arr.push(byDay[new Date(d.now + 9 * 3600e3 - i * 864e5).toISOString().slice(0, 10)] || 0);\n  var act = arr.filter(Boolean).length;\n  h += '<h2>14 วันที่ผ่านมา <small>ทำ ' + act + ' จาก 14 วัน · ' + arr.reduce(function(a, b){ return a + b; }, 0) + ' ข้อ</small></h2><div class=\"panel track14\">' + arr.map(function(v){ return '<i class=\"' + (v ? v >= 40 ? 'l3' : v >= 15 ? 'l2' : 'l1' : '') + '\" title=\"' + v + ' ข้อ\"></i>'; }).join('') + '</div>';\n  h += '<details class=\"extra\"><summary>ประวัติล่าสุด</summary><div class=\"panel\" style=\"margin-top:10px\">' + (d.events.length ? '<table><tr><th>เวลา</th><th>ทำอะไร</th><th class=\"n\">คะแนน</th></tr>' + d.events.slice(0, 40).map(function(e){ return '<tr><td>' + ago(e.ts, d.now) + '</td><td>' + (PART[e.part] || e.part) + ' · ' + (MODE[e.mode] || e.mode) + '</td><td class=\"n\">' + e.s + '/' + e.n + '</td></tr>'; }).join('') + '</table>' : '<div class=\"empty\">ยังไม่มี</div>') + '</div></details></div>';\n  $('dlgBody').innerHTML = h;\n}\ndocument.addEventListener('click', function(e){\n  var r = e.target.closest('.prow'); if (r) { openPerson(r.dataset.k); return; }\n  var t = e.target.closest('[data-tab]'); if (t) { dpTab = t.dataset.tab; var y = $('dlg').scrollTop; drawPerson(); $('dlg').scrollTop = y; return; }\n  if (e.target.closest('#dlgClose')) { $('dlg').close(); return; }\n  if (e.target.closest('#showAll')) { showAll = !showAll; renderPeople(last); }\n});\n$('dlg').addEventListener('click', function(e){ if (e.target === $('dlg')) $('dlg').close(); });\nvar KEY = ''; try { KEY = localStorage.getItem('jac-statskey') || ''; } catch (e) {}\nfunction load(){\n  fetch('/api/stats', { cache: 'no-store', headers: { 'x-key': KEY } }).then(function(r){\n    if (r.status === 401) { $('gate').style.display = 'block'; $('dash').hidden = true; $('live').innerHTML = '<span class=\"dot\"></span>ล็อกอยู่'; if (KEY) $('gmsg').textContent = 'รหัสผ่านไม่ถูกต้อง'; throw 'key'; }\n    return r.json();\n  }).then(function(d){ $('gate').style.display = 'none'; render(d); }).catch(function(e){ if (e !== 'key') $('live').innerHTML = '<span class=\"dot\"></span>โหลดไม่ได้'; });\n}\n$('go').onclick = function(){ KEY = $('key').value.trim(); try { localStorage.setItem('jac-statskey', KEY); } catch (e) {} load(); };\n$('key').onkeydown = function(e){ if (e.key === 'Enter') $('go').click(); };\nload(); setInterval(function(){ if (KEY && !$('dlg').open) load(); }, 30000);\n</script>\n</body></html>\n";
